--
-- Trigger `detail_pembayaran_pasien`
--
DELIMITER $$
CREATE TRIGGER `after_delete_detail_pembayaran_pasien` AFTER DELETE ON `detail_pembayaran_pasien` FOR EACH ROW BEGIN
                UPDATE pembayaran_pasien
                SET total_biaya = (
                    SELECT COALESCE(SUM(subtotal), 0)
                    FROM detail_pembayaran_pasien
                    WHERE pembayaran_id = OLD.pembayaran_id
                )
                WHERE id = OLD.pembayaran_id;
            END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `after_insert_detail_pembayaran_pasien` AFTER INSERT ON `detail_pembayaran_pasien` FOR EACH ROW BEGIN
                UPDATE pembayaran_pasien
                SET total_biaya = (
                    SELECT COALESCE(SUM(subtotal), 0)
                    FROM detail_pembayaran_pasien
                    WHERE pembayaran_id = NEW.pembayaran_id
                )
                WHERE id = NEW.pembayaran_id;
            END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `after_update_detail_pembayaran_pasien` AFTER UPDATE ON `detail_pembayaran_pasien` FOR EACH ROW BEGIN
                IF OLD.pembayaran_id != NEW.pembayaran_id THEN
                    UPDATE pembayaran_pasien
                    SET total_biaya = COALESCE((
                        SELECT SUM(subtotal)
                        FROM detail_pembayaran_pasien
                        WHERE pembayaran_id = OLD.pembayaran_id
                    ), 0)
                    WHERE id = OLD.pembayaran_id;

                    UPDATE pembayaran_pasien
                    SET total_biaya = COALESCE((
                        SELECT SUM(subtotal)
                        FROM detail_pembayaran_pasien
                        WHERE pembayaran_id = NEW.pembayaran_id
                    ), 0)
                    WHERE id = NEW.pembayaran_id;
                ELSE
                    UPDATE pembayaran_pasien
                    SET total_biaya = COALESCE((
                        SELECT SUM(subtotal)
                        FROM detail_pembayaran_pasien
                        WHERE pembayaran_id = NEW.pembayaran_id
                    ), 0)
                    WHERE id = NEW.pembayaran_id;
                END IF;
            END
$$
DELIMITER ;

