CREATE TABLE `detail_pembelian_obat` (
  `id` bigint UNSIGNED NOT NULL,
  `pembelian_id` bigint UNSIGNED NOT NULL,
  `obat_id` bigint UNSIGNED NOT NULL,
  `jumlah` int NOT NULL,
  `harga_satuan` decimal(15,2) NOT NULL,
  `harga_beli` decimal(15,2) NOT NULL,
  `subtotal` decimal(15,2) NOT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Trigger `detail_pembelian_obat`
--
DELIMITER $$
CREATE TRIGGER `after_insert_detail_pembelian_obat` AFTER INSERT ON `detail_pembelian_obat` FOR EACH ROW BEGIN
                DECLARE stok_lama INT;
                DECLARE stok_baru INT;

                SELECT stok INTO stok_lama
                FROM obat
                WHERE id = NEW.obat_id
                LIMIT 1;

                SET stok_baru = stok_lama + NEW.jumlah;

                UPDATE obat
                SET stok = stok_baru
                WHERE id = NEW.obat_id;

                INSERT INTO log_stok_obat (
                    obat_id,
                    jenis,
                    jumlah,
                    stok_sebelum,
                    stok_sesudah,
                    referensi_id,
                    created_at
                ) VALUES (
                    NEW.obat_id,
                    'MASUK',
                    NEW.jumlah,
                    stok_lama,
                    stok_baru,
                    NEW.pembelian_id,
                    NOW()
                );
            END
$$
DELIMITER ;
