--
-- Trigger `rawat_inap`
--
DELIMITER $$
CREATE TRIGGER `after_update_rawat_inap_aktif` AFTER UPDATE ON `rawat_inap` FOR EACH ROW BEGIN
                IF NEW.status = 'Aktif' THEN

                    INSERT INTO log_ruangan (
                        ruangan_id,
                        rawat_inap_id,
                        pasien_id,
                        status_sebelum,
                        status_sesudah,
                        aksi,
                        waktu
                    ) VALUES (
                        OLD.ruangan_id,
                        OLD.id,
                        OLD.pasien_id,
                        'tersedia',
                        'tidak_tersedia',
                        'MASUK',
                        NOW()
                    );

                    UPDATE ruangan
                    SET status = 'tidak_tersedia'
                    WHERE id = OLD.ruangan_id;

                END IF;
            END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `after_update_rawat_inap_pindah` AFTER UPDATE ON `rawat_inap` FOR EACH ROW BEGIN
                IF OLD.ruangan_id <> NEW.ruangan_id THEN

                    -- LOG KELUAR RUANGAN LAMA
                    INSERT INTO log_ruangan (
                        ruangan_id,
                        rawat_inap_id,
                        pasien_id,
                        status_sebelum,
                        status_sesudah,
                        aksi,
                        waktu
                    ) VALUES (
                        OLD.ruangan_id,
                        OLD.id,
                        OLD.pasien_id,
                        'tidak_tersedia',
                        'tersedia',
                        'PINDAH_KELUAR',
                        NOW()
                    );

                    -- LOG MASUK RUANGAN BARU
                    INSERT INTO log_ruangan (
                        ruangan_id,
                        rawat_inap_id,
                        pasien_id,
                        status_sebelum,
                        status_sesudah,
                        aksi,
                        waktu
                    ) VALUES (
                        NEW.ruangan_id,
                        OLD.id,
                        OLD.pasien_id,
                        'tersedia',
                        'tidak_tersedia',
                        'PINDAH_MASUK',
                        NOW()
                    );

                    UPDATE ruangan SET status = 'tersedia' WHERE id = OLD.ruangan_id;
                    UPDATE ruangan SET status = 'tidak_tersedia' WHERE id = NEW.ruangan_id;

                END IF;
            END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `after_update_rawat_inap_pulang` AFTER UPDATE ON `rawat_inap` FOR EACH ROW BEGIN
                IF NEW.status = 'Pulang' THEN

                    INSERT INTO log_ruangan (
                        ruangan_id,
                        rawat_inap_id,
                        pasien_id,
                        status_sebelum,
                        status_sesudah,
                        aksi,
                        waktu
                    ) VALUES (
                        OLD.ruangan_id,
                        OLD.id,
                        OLD.pasien_id,
                        'tidak_tersedia',
                        'tersedia',
                        'PULANG',
                        NOW()
                    );

                    UPDATE ruangan
                    SET status = 'tersedia'
                    WHERE id = OLD.ruangan_id;

                END IF;
            END
$$
DELIMITER ;

