--
-- Trigger `resep_obat`
--
DELIMITER $$
CREATE TRIGGER `trg_resep_obat_after_delete` AFTER DELETE ON `resep_obat` FOR EACH ROW BEGIN
                UPDATE obat
                SET stok = stok + OLD.jumlah
                WHERE id = OLD.obat_id;
            END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_resep_obat_after_insert` AFTER INSERT ON `resep_obat` FOR EACH ROW BEGIN
                UPDATE obat
                SET stok = stok - NEW.jumlah
                WHERE id = NEW.obat_id;
            END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_resep_obat_after_update` AFTER UPDATE ON `resep_obat` FOR EACH ROW BEGIN
                -- Jika obat tidak berubah
                IF OLD.obat_id = NEW.obat_id THEN
                    UPDATE obat
                    SET stok = stok + OLD.jumlah - NEW.jumlah
                    WHERE id = NEW.obat_id;
                ELSE
                    -- Kembalikan stok obat lama
                    UPDATE obat
                    SET stok = stok + OLD.jumlah
                    WHERE id = OLD.obat_id;

                    -- Kurangi stok obat baru
                    UPDATE obat
                    SET stok = stok - NEW.jumlah
                    WHERE id = NEW.obat_id;
                END IF;
            END
$$
DELIMITER ;

